custom_css:
/* 
酒馆美化：万蝶振翅
作者：芜眠
禁止二传倒卖，二改随意
编号章节用于定位功能；🦋 标记素材、尺寸与配色等常用调节项。
消息拼贴的 cqw 以聊天容器宽度计算，100cqw = 聊天区宽度。 */

/* ===== 01 | 字体与全局基础 ===== */

/* --- 全局字体替换 by Deleted User --- */
/* 01.1 全局字体：正文、代码与表单统一字体，保留图标字形。 */
@import url("https://fontsapi.zeoseven.com/285/main/result.css");

:root,
body {
  --mainFontFamily: "Noto Serif CJK", serif;
  --monoFontFamily: var(--mainFontFamily);
}

body {
  /* 方框勾选颜色 */
  --wd-checkbox-color: var(--SmartThemeBodyColor, #416089);
  /* 🦋 顶栏整体倍率；原生高度变量同步控制聊天与抽屉起点。 */
  --wd-top-scale: 2.0;
  --topBarBlockSize: calc((var(--topBarIconSize) + var(--topBarBlockPadding)) * var(--wd-top-scale));
  font-family: var(--mainFontFamily);
  font-weight: normal;
}

body :is(input, textarea, select, option, optgroup, button,
  pre, code, kbd, samp, .monospace, .ui-widget, .select2-search__field):not(.fa, .fas, .far, .fab, .fal, .fad, .fat,
    .fa-solid, .fa-regular, .fa-brands, .fa-light, .fa-thin, .fa-duotone,
    .fa-sharp, .fa-sharp-duotone, .fa-classic),
#chat :is(.mes_text, .mes_reasoning),
#chat :is(.mes_text, .mes_reasoning)
  :is(div, span, p, h1, h2, h3, h4, h5, h6, blockquote, q,
    pre, code, kbd, samp, var, strong, b, em, i, u, s, del, ins,
    mark, small, sub, sup, a, ul, ol, li, dl, dt, dd,
    table, caption, thead, tbody, tfoot, tr, th, td,
    details, summary, ruby, rt, rp, label):not(.fa, .fas, .far, .fab, .fal, .fad, .fat,
    .fa-solid, .fa-regular, .fa-brands, .fa-light, .fa-thin, .fa-duotone,
    .fa-sharp, .fa-sharp-duotone, .fa-classic) {
  font-family: var(--mainFontFamily) !important;
}

/* --- 去除全局阴影 by 在到处之间找我 --- */
/* 01.2 去除阴影、滤镜投影与手动缩放角标，隐藏滚动条外观。 */
*,
*::before,
*::after {
  box-shadow: none !important;
  text-shadow: none !important;
  filter: none !important;
}

/* --- 去除输入框右下角缩放点 by nini --- */
body * {
  resize: none !important;
  scrollbar-width: none;
}

::-webkit-scrollbar {
  display: none;
}

/* --- 勾选框样式 by Nakari --- */
/* 01.3 通用方框勾选：区分未选、已选、混合状态与键盘焦点。 */
body input[type="checkbox"] {
  background: transparent;
  border: 1px solid var(--wd-checkbox-color);
  border-radius: 3px;
  outline: none;
}

body input[type="checkbox"]:checked {
  background-color: var(--wd-checkbox-color);
}

body input[type="checkbox"]:indeterminate {
  outline: 1px dashed var(--wd-checkbox-color);
  outline-offset: 2px;
}

body input[type="checkbox"]:focus-visible {
  outline: 2px solid var(--wd-checkbox-color);
  outline-offset: 2px;
}

/* Select2 选项使用独立伪元素，选中时清除自带勾号。 */
.select2-container .select2-results__option::before {
  content: "";
  border: 1px solid var(--wd-checkbox-color);
  background: transparent;
}

.select2-container .select2-results__option.select2-results__option--selected::before {
  content: "";
  background-color: var(--wd-checkbox-color);
}

/* ===== 02 | 聊天区域与消息卡片 ===== */

/* --- 消息气泡拼贴美化模板 by Nakari、lazyaile --- */
/* 02.1 聊天容器与拼贴参数 */
#sheld {
  container-type: inline-size;
  /* 🦋 底栏渐变距离；聊天区与底栏共用同一计算宽度。 */
  --wd-bottom-fade-reach: clamp(60px, 10cqw, 100px);
}

#chat {
  container-type: inline-size;
  /* 🦋 三段背景与消息按钮素材 */
  --wd-head-image: url("https://qianqianqiu.date/file/studio/CmWxQ3GdSNPHudzy.png");
  --wd-middle-image: url("https://qianqianqiu.date/file/studio/eMzvL1ctgup4L2U1.png");
  --wd-tail-image: url("https://qianqianqiu.date/file/studio/l1U2QqMHt3vs6TaH.png");
  --wd-menu-image: url("https://qianqianqiu.date/file/studio/hAaJEkPXUnenKuQq.png");
  --wd-edit-image: url("https://qianqianqiu.date/file/studio/LaZpTgxiwPHtaWcN.png");
  --wd-reasoning-image: url("https://qianqianqiu.date/file/studio/rG32DqtoYsipwW6T.png");
  --wd-last-image: url("https://qianqianqiu.date/file/studio/9wOpmSCDG4UXxjsA.png");
  --wd-next-image: url("https://qianqianqiu.date/file/studio/1YYpy7grn1WfHV2v.png");
  /* 🦋 消息信息、页码与纸面颜色 */
  --wd-meta-color: #576C85;
  --wd-page-color: #3E5F84;
  --wd-paper-color: #CFD9E6;
  /* 头尾高度按素材比例换算；中段随正文延展。 */
  --wd-head-height: 88.888889cqw;
  --wd-tail-height: 2.747909cqw;
  /* 🦋 短消息最小留白、正文两侧内边距与页脚空间 */
  --wd-body-min-height: 60.5cqw;
  --wd-text-inset: 7.5cqw;
  --wd-footer-space: 9cqw;
  /* 🦋【头像容器尺寸修改位置】在这里调整聊天头像大小： */
  --wd-avatar-left: 16.905cqw;   /* 🦋 头像容器水平位置cqw */
  --wd-avatar-top: 23.44cqw;     /* 🦋 头像容器垂直位置cqw */
  --wd-avatar-width: 33.3cqw;    /* 🦋【修改头像大小：宽度】 */
  --wd-avatar-height: 28.9cqw;   /* 🦋【修改头像大小：高度】 */
  --wd-avatar-position: 50% 50%; /* 🦋 头像图像的裁切中心 */
  /* 🦋 名字与楼层／用时／Tokens 的位置和字号 */
  --wd-name-top: 12.65cqw;
  --wd-name-left: 53.3cqw;
  --wd-name-width: 42.5cqw;
  --wd-name-size: clamp(9px, 2.1cqw, 24px);
  --wd-stats-top: 15.85cqw;
  --wd-stats-size: clamp(6.5px, 1.35cqw, 15px);
  /* 🦋 头像下方时间戳的位置和字号 */
  --wd-time-top: 52.35cqw;
  --wd-time-left: 29.1cqw;
  --wd-time-width: 20cqw;
  --wd-time-size: clamp(6px, 1.55cqw, 18px);
  /* 🦋 更多／编辑按钮组；top 为垂直中心。 */
  --wd-actions-top: 68.6cqw;
  --wd-actions-left: 71.9cqw;
  --wd-actions-width: 20.2cqw;
  /* 🦋 思维链图片入口；top 为垂直中心。 */
  --wd-reasoning-top: 74.3cqw;
  --wd-reasoning-left: 23cqw;
  --wd-reasoning-width: 52cqw;
}

/* 聊天区与底栏渐变重叠；下内边距保证末条消息可完整滚出渐变区。 */
#sheld > #chat {
  min-height: 0;
  margin-bottom: calc(-1 * var(--wd-bottom-fade-reach));
  padding-bottom: var(--wd-bottom-fade-reach);
  scroll-padding-bottom: var(--wd-bottom-fade-reach);
}

/* 02.2 消息主体：角色与用户在显示／隐藏时共用拼贴。
   隐藏消息也会被标记为 is_system=true，不能单凭此属性排除。
   原生系统提示、紧凑提示与工具调用保留原生布局。 */
#chat > .mes:is([is_system="false"], [is_system="true"]:not(.smallSysMes, .toolCall, [ch_name="SillyTavern System"])) {
  position: relative;
  isolation: isolate;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  flex: 0 0 auto;
  width: 100%;
  max-width: 100%;
  min-width: 0;
  box-sizing: border-box;
  margin: 0 0 3cqw;
  padding: 0 !important;
  border: 0;
  border-radius: 0;
  background: transparent;
  overflow: visible;
}

/* 外层不建立定位框；按钮相对整条消息，名字与幽灵共用内层一行。 */
#chat > .mes:is([is_system="false"], [is_system="true"]:not(.smallSysMes, .toolCall, [ch_name="SillyTavern System"])) > .mes_block > .ch_name,
#chat > .mes:is([is_system="false"], [is_system="true"]:not(.smallSysMes, .toolCall, [ch_name="SillyTavern System"])) > .mes_block > .ch_name > .flex-container {
  display: contents;
}

#chat > .mes:is([is_system="false"], [is_system="true"]:not(.smallSysMes, .toolCall, [ch_name="SillyTavern System"])) > .mes_block > .ch_name > .flex-container > .flex-container {
  position: absolute;
  top: var(--wd-name-top);
  left: var(--wd-name-left);
  display: flex;
  flex-direction: row;
  flex-wrap: nowrap;
  align-items: center;
  justify-content: center;
  gap: 0.45cqw;
  width: var(--wd-name-width);
  min-width: 0;
  margin: 0;
  padding: 0;
  z-index: 3;
}

/* 02.3 三段式背景：头图固定比例，中段纵向平铺，尾图随正文下移。 */
/* 头像包裹层保留静态定位；楼层、用时与 Tokens 在同一行自然排列。 */
#chat > .mes:is([is_system="false"], [is_system="true"]:not(.smallSysMes, .toolCall, [ch_name="SillyTavern System"])) > .mesAvatarWrapper {
  position: static;
  display: flex;
  flex: 0 0 auto;
  justify-content: center;
  align-items: flex-start;
  gap: 0.65cqw;
  width: 100%;
  height: var(--wd-head-height);
  min-height: 0;
  box-sizing: border-box;
  margin: 0;
  padding: var(--wd-stats-top) 4.2cqw 0 53.3cqw;
  background: none;
  transform: none;
}

/* 头图覆盖头像边缘；装饰层不接收点击。 */
#chat > .mes:is([is_system="false"], [is_system="true"]:not(.smallSysMes, .toolCall, [ch_name="SillyTavern System"]))::before {
  content: "";
  position: absolute;
  inset: 0 0 auto;
  width: 100%;
  height: var(--wd-head-height);
  background: var(--wd-head-image) center top / 100% 100% no-repeat;
  z-index: 2;
  pointer-events: none;
}

#chat > .mes:is([is_system="false"], [is_system="true"]:not(.smallSysMes, .toolCall, [ch_name="SillyTavern System"])) > .mes_block {
  position: static;
  flex: 0 0 auto;
  width: 100%;
  min-width: 0;
  min-height: var(--wd-body-min-height);
  box-sizing: border-box;
  margin: 0;
  padding: 0 var(--wd-text-inset) var(--wd-footer-space);
  background-image: var(--wd-middle-image),
    linear-gradient(to right, transparent 3.5%, var(--wd-paper-color) 3.5%, var(--wd-paper-color) 96.5%, transparent 96.5%);
  background-position: center top;
  background-size: 100% auto, 100% 100%;
  background-repeat: repeat-y, no-repeat;
  border: 0;
  border-radius: 0;
  transform: none !important;
  overflow: visible !important;
}

#chat > .mes:is([is_system="false"], [is_system="true"]:not(.smallSysMes, .toolCall, [ch_name="SillyTavern System"]))::after {
  content: "";
  position: relative;
  display: block;
  flex: 0 0 auto;
  width: 100%;
  height: var(--wd-tail-height);
  margin: 0;
  background: var(--wd-tail-image) center top / 100% 100% no-repeat;
  z-index: 0;
  pointer-events: none;
}

/* 02.4 消息头像：填满拍立得开口，裁切中心由 --wd-avatar-position 调节。 */
#chat > .mes:is([is_system="false"], [is_system="true"]:not(.smallSysMes, .toolCall, [ch_name="SillyTavern System"])) > .mesAvatarWrapper > .avatar {
  position: absolute;
  top: var(--wd-avatar-top);
  left: var(--wd-avatar-left);
  right: auto;
  bottom: auto;
  width: var(--wd-avatar-width) !important;
  height: var(--wd-avatar-height) !important;
  max-width: none;
  max-height: none;
  min-width: 0;
  flex: none;
  margin: 0;
  padding: 0;
  border: 0 !important;
  border-radius: 0 !important;
  background: var(--wd-paper-color);
  transform: none;
  overflow: hidden;
  z-index: 1;
  /* 排除上下文时不淡化拍立得头像。 */
  opacity: 1;
  filter: none;
}

#chat > .mes:is([is_system="false"], [is_system="true"]:not(.smallSysMes, .toolCall, [ch_name="SillyTavern System"])) > .mesAvatarWrapper > .avatar > img {
  display: block;
  width: 100% !important;
  height: 100% !important;
  max-width: none;
  max-height: none;
  margin: 0;
  padding: 0;
  object-fit: cover;
  object-position: var(--wd-avatar-position);
  border: 0 !important;
  border-radius: 0 !important;
}

/* 02.5 名字、楼层、用时、Tokens 与时间戳 */
#chat > .mes:is([is_system="false"], [is_system="true"]:not(.smallSysMes, .toolCall, [ch_name="SillyTavern System"])) .name_text,
#chat > .mes:is([is_system="false"], [is_system="true"]:not(.smallSysMes, .toolCall, [ch_name="SillyTavern System"])) .timestamp,
#chat > .mes:is([is_system="false"], [is_system="true"]:not(.smallSysMes, .toolCall, [ch_name="SillyTavern System"])) .mesIDDisplay,
#chat > .mes:is([is_system="false"], [is_system="true"]:not(.smallSysMes, .toolCall, [ch_name="SillyTavern System"])) .mes_timer,
#chat > .mes:is([is_system="false"], [is_system="true"]:not(.smallSysMes, .toolCall, [ch_name="SillyTavern System"])) .tokenCounterDisplay {
  color: var(--wd-meta-color) !important;
  font-family: var(--mainFontFamily);
  font-weight: 400;
  font-style: normal;
  letter-spacing: 0;
  line-height: 1.2;
  opacity: 1;
  z-index: 3;
  margin: 0;
  padding: 0;
  white-space: nowrap;
}

#chat > .mes:is([is_system="false"], [is_system="true"]:not(.smallSysMes, .toolCall, [ch_name="SillyTavern System"])) .name_text {
  position: static;
  flex: 0 1 auto;
  min-width: 0;
  max-width: 100%;
  width: auto;
  font-size: var(--wd-name-size);
  text-align: center;
  overflow: hidden;
  text-overflow: ellipsis;
}

#chat > .mes:is([is_system="false"], [is_system="true"]:not(.smallSysMes, .toolCall, [ch_name="SillyTavern System"])) .mesIDDisplay,
#chat > .mes:is([is_system="false"], [is_system="true"]:not(.smallSysMes, .toolCall, [ch_name="SillyTavern System"])) .mes_timer,
#chat > .mes:is([is_system="false"], [is_system="true"]:not(.smallSysMes, .toolCall, [ch_name="SillyTavern System"])) .tokenCounterDisplay {
  position: relative;
  flex: 0 1 auto;
  min-width: 0;
  font-size: var(--wd-stats-size);
  text-align: center;
}

/* 动态数值为空时隐藏对应标签；名称、时间及统计信息沿用真实消息数据。 */
#chat > .mes:is([is_system="false"], [is_system="true"]:not(.smallSysMes, .toolCall, [ch_name="SillyTavern System"])) .mesIDDisplay:not(:empty)::before {
  content: "蝴蝶\00a0 ";
}

#chat > .mes:is([is_system="false"], [is_system="true"]:not(.smallSysMes, .toolCall, [ch_name="SillyTavern System"])) .mes_timer:not(:empty)::before {
  content: "逐风\00a0 ";
}

#chat > .mes:is([is_system="false"], [is_system="true"]:not(.smallSysMes, .toolCall, [ch_name="SillyTavern System"])) .tokenCounterDisplay:not(:empty)::before {
  content: "振翅\00a0 ";
}

#chat > .mes:is([is_system="false"], [is_system="true"]:not(.smallSysMes, .toolCall, [ch_name="SillyTavern System"])) .mesIDDisplay:empty,
#chat > .mes:is([is_system="false"], [is_system="true"]:not(.smallSysMes, .toolCall, [ch_name="SillyTavern System"])) .mes_timer:empty,
#chat > .mes:is([is_system="false"], [is_system="true"]:not(.smallSysMes, .toolCall, [ch_name="SillyTavern System"])) .tokenCounterDisplay:empty {
  display: none;
}

#chat > .mes:is([is_system="false"], [is_system="true"]:not(.smallSysMes, .toolCall, [ch_name="SillyTavern System"])) .timestamp {
  position: absolute;
  /* 内层名字行成为定位框后，抵消它的偏移，保持原有时间戳坐标。 */
  top: calc(var(--wd-time-top) - var(--wd-name-top));
  left: calc(var(--wd-time-left) - var(--wd-name-left));
  width: var(--wd-time-width);
  font-size: var(--wd-time-size);
  text-align: right;
}

/* 原生显隐仍由 is_system 控制；幽灵紧随名字，不参与缩小或省略。 */
#chat > .mes:is([is_system="false"], [is_system="true"]:not(.smallSysMes, .toolCall, [ch_name="SillyTavern System"])) .mes_ghost {
  position: static;
  flex: 0 0 auto;
  margin: 0;
  padding: 0;
  color: var(--wd-meta-color);
  font-size: clamp(8px, 1.6cqw, 16px);
  line-height: 1;
  opacity: 1;
}

/* ===== 03 | 消息操作与翻页 ===== */

/* 03.1 更多、编辑与翻页按钮共用图片绘制层。 */
/* 关闭原图标伪元素，保留点击宿主、功能提示与原生显隐。 */
#chat > .mes:is([is_system="false"], [is_system="true"]:not(.smallSysMes, .toolCall, [ch_name="SillyTavern System"])) .extraMesButtonsHint::before,
#chat > .mes:is([is_system="false"], [is_system="true"]:not(.smallSysMes, .toolCall, [ch_name="SillyTavern System"])) .mes_edit::before,
#chat > .mes:is([is_system="false"], [is_system="true"]:not(.smallSysMes, .toolCall, [ch_name="SillyTavern System"])) .swipe_left::before,
#chat > .mes:is([is_system="false"], [is_system="true"]:not(.smallSysMes, .toolCall, [ch_name="SillyTavern System"])) .swipe_right::before {
  content: none;
}

#chat > .mes:is([is_system="false"], [is_system="true"]:not(.smallSysMes, .toolCall, [ch_name="SillyTavern System"])) .extraMesButtonsHint::after,
#chat > .mes:is([is_system="false"], [is_system="true"]:not(.smallSysMes, .toolCall, [ch_name="SillyTavern System"])) .mes_edit::after,
#chat > .mes:is([is_system="false"], [is_system="true"]:not(.smallSysMes, .toolCall, [ch_name="SillyTavern System"])) .swipe_left::after,
#chat > .mes:is([is_system="false"], [is_system="true"]:not(.smallSysMes, .toolCall, [ch_name="SillyTavern System"])) .swipe_right::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  background-position: center;
  background-repeat: no-repeat;
  background-size: contain;
  pointer-events: none;
}

/* 03.2 更多与编辑按钮 */
#chat > .mes:is([is_system="false"], [is_system="true"]:not(.smallSysMes, .toolCall, [ch_name="SillyTavern System"])) .mes_buttons {
  position: absolute;
  top: var(--wd-actions-top);
  left: var(--wd-actions-left);
  right: auto;
  width: var(--wd-actions-width);
  min-width: 0;
  margin: 0;
  padding: 0;
  gap: 0;
  align-items: center;
  justify-content: space-between;
  transform: translateY(-50%);
  overflow: visible;
  z-index: 5;
}

#chat > .mes:is([is_system="false"], [is_system="true"]:not(.smallSysMes, .toolCall, [ch_name="SillyTavern System"])) .mes_buttons > .extraMesButtonsHint,
#chat > .mes:is([is_system="false"], [is_system="true"]:not(.smallSysMes, .toolCall, [ch_name="SillyTavern System"])) .mes_buttons > .mes_edit {
  position: relative;
  flex: 0 0 8.4cqw;
  width: 8.4cqw;
  height: max(24px, 4.6cqw);
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--wd-page-color);
  opacity: 1;
}

#chat > .mes:is([is_system="false"], [is_system="true"]:not(.smallSysMes, .toolCall, [ch_name="SillyTavern System"])) .mes_buttons > .mes_edit {
  margin-left: auto;
}

#chat > .mes:is([is_system="false"], [is_system="true"]:not(.smallSysMes, .toolCall, [ch_name="SillyTavern System"])) .extraMesButtonsHint::after {
  width: 5.8cqw;
  height: 1.691667cqw;
  background-image: var(--wd-menu-image);
}

#chat > .mes:is([is_system="false"], [is_system="true"]:not(.smallSysMes, .toolCall, [ch_name="SillyTavern System"])) .mes_edit::after {
  width: 4.6cqw;
  height: 2.3cqw;
  background-image: var(--wd-edit-image);
}

/* 更多面板在编辑按钮左侧展开，项目较多时换行。 */
#chat > .mes:is([is_system="false"], [is_system="true"]:not(.smallSysMes, .toolCall, [ch_name="SillyTavern System"])) .extraMesButtons {
  position: absolute;
  top: 50%;
  right: 11.8cqw;
  transform: translateY(-50%);
  width: max-content;
  max-width: 72.8cqw;
