/* ===== 05 | 顶栏背景与导航图标 ===== */

/* 05.1 云蓝背景与向下渐隐蒙版 */
/* 背景独立延伸，不占按钮布局空间，也不接收点击。 */
#top-bar,
body.no-blur #top-bar {
  /* 🦋 顶栏背景素材 */
  --wd-top-background: url("https://qianqianqiu.date/file/studio/g2lRbv6gUNVnmFxX.png");
  /* 🦋 渐变距离与透明度曲线 */
  --wd-top-fade-reach: clamp(60px, calc(var(--sheldWidth) / 10), 100px);
  --wd-top-fade: linear-gradient(
    to top,
    transparent 0,
    rgba(0, 0, 0, 0.02) calc(var(--wd-top-fade-reach) * 0.06),
    rgba(0, 0, 0, 0.12) calc(var(--wd-top-fade-reach) * 0.18),
    rgba(0, 0, 0, 0.37) calc(var(--wd-top-fade-reach) * 0.35),
    rgba(0, 0, 0, 0.68) calc(var(--wd-top-fade-reach) * 0.55),
    rgba(0, 0, 0, 0.90) calc(var(--wd-top-fade-reach) * 0.75),
    rgba(0, 0, 0, 0.98) calc(var(--wd-top-fade-reach) * 0.90),
    #000 var(--wd-top-fade-reach),
    #000 100%
  );
  height: calc(var(--topBarBlockSize) + var(--wd-top-fade-reach));
  background: #D5DFEC var(--wd-top-background) center / max(calc(100% * var(--wd-top-scale)), calc((var(--topBarBlockSize) + var(--wd-top-fade-reach)) * 4.894737)) auto no-repeat !important;
  border: 0;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  -webkit-mask-image: var(--wd-top-fade);
  mask-image: var(--wd-top-fade);
  -webkit-mask-size: 100% 100%;
  mask-size: 100% 100%;
  -webkit-mask-repeat: no-repeat;
  mask-repeat: no-repeat;
  mask-mode: alpha;
  pointer-events: none;
}

