  border-radius: 4px;
  background: transparent;
  vertical-align: middle;
  opacity: 1;
}

#top-settings-holder > .drawer:nth-of-type(-n+10) > .drawer-toggle > .drawer-icon::before {
  content: none;
}

#top-settings-holder > .drawer:nth-of-type(-n+10) > .drawer-toggle > .drawer-icon::after {
  content: "";
  position: absolute;
  top: var(--wd-top-icon-y);
  left: var(--wd-top-icon-x);
  width: var(--wd-top-icon-size);
  height: var(--wd-top-icon-size);
  transform: translate(-50%, -50%) rotate(var(--wd-top-icon-tilt));
  transition: transform 180ms ease;
  background: var(--wd-top-icon) center / contain no-repeat;
  pointer-events: none;
}

/* 05.5 展开、悬停与键盘焦点 */
#top-settings-holder > .drawer:nth-of-type(-n+10) > .drawer-toggle > .drawer-icon.closedIcon {
  opacity: 0.85;
}

#top-settings-holder > .drawer:nth-of-type(-n+10) > .drawer-toggle > .drawer-icon:is(.openIcon, :hover, :focus-visible) {
  opacity: 1;
}

#top-settings-holder > .drawer:nth-of-type(-n+10) > .drawer-toggle > .drawer-icon:hover::after {
  transform: translate(-50%, -50%) rotate(var(--wd-top-icon-tilt)) scale(1.2);
}

#top-settings-holder > .drawer:nth-of-type(-n+10) > .drawer-toggle > .drawer-icon:focus-visible {
  outline: 2px solid var(--wd-top-active-color);
  outline-offset: -2px;
}

/* ===== 06 | 输入栏与发送控件 ===== */

/* 06.1 底栏容器与交互区域 */
/* 顶部留出渐变空间；装饰区允许事件穿透，输入和删除控件恢复交互。 */
#sheld > #form_sheld {
  --wd-bottom-background: url("https://qianqianqiu.date/file/studio/2ZAAoQThBVFv7god.png");
  position: relative;
  z-index: 31;
  flex-shrink: 0;
  box-sizing: border-box;
  margin-top: 0;
  padding-top: var(--wd-bottom-fade-reach);
  overflow: visible;
  pointer-events: none;
}

#sheld > #form_sheld > :is(#send_form, #dialogue_del_mes) {
  pointer-events: auto;
}

/* 普通与快速界面共用透明底板；背景统一由外层装饰层绘制。 */
#send_form,
body.no-blur #send_form {
  container-type: inline-size;
  /* 🦋 按钮尺寸、输入框高度与提示颜色 */
  --wd-bottom-button: clamp(40px, 10.8cqw, 96px);
  --wd-bottom-input-height: clamp(40px, 6.24cqw, 56px);
  --wd-bottom-hint-color: #576B83;
  --bottomFormBlockSize: var(--wd-bottom-button);
  border: 0 !important;
  border-radius: 0;
  background: transparent !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}

/* 输入框聚焦时仅保留自身轮廓。 */
#send_form:has(#send_textarea:focus-visible) {
  outline: none;
}

/* 06.2 输入布局：左侧菜单与扩展，中间输入框，右侧 QR 与发送／停止。 */
#send_form > #nonQRFormItems {
  position: relative;
  isolation: isolate;
  overflow: visible;
  display: grid;
  grid-template-columns: calc(var(--wd-bottom-button) * 2) minmax(0, 1fr) calc(var(--wd-bottom-button) * 2);
  align-items: center;
  column-gap: clamp(1px, 0.3cqw, 3px);
  box-sizing: border-box;
  min-width: 0;
  padding: clamp(12px, 5.49cqw, 49px) clamp(1px, 0.3cqw, 3px) clamp(8px, 3.048cqw, 27px) clamp(12px, 4.5cqw, 40px);
  background: transparent;
}

/* 06.3 底栏背景与向上渐隐蒙版 */
#sheld > #form_sheld::before {
  --wd-bottom-fade: linear-gradient(
    to bottom,
    transparent 0,
    rgba(0, 0, 0, 0.02) calc(var(--wd-bottom-fade-reach) * 0.06),
    rgba(0, 0, 0, 0.12) calc(var(--wd-bottom-fade-reach) * 0.18),
    rgba(0, 0, 0, 0.37) calc(var(--wd-bottom-fade-reach) * 0.35),
    rgba(0, 0, 0, 0.68) calc(var(--wd-bottom-fade-reach) * 0.55),
    rgba(0, 0, 0, 0.90) calc(var(--wd-bottom-fade-reach) * 0.75),
    rgba(0, 0, 0, 0.98) calc(var(--wd-bottom-fade-reach) * 0.90),
    #000 var(--wd-bottom-fade-reach),
    #000 100%
  );
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  background: #AFC1D8 var(--wd-bottom-background) center bottom / cover no-repeat;
  -webkit-mask-image: var(--wd-bottom-fade);
  mask-image: var(--wd-bottom-fade);
  -webkit-mask-size: 100% 100%;
  mask-size: 100% 100%;
  -webkit-mask-repeat: no-repeat;
  mask-repeat: no-repeat;
  mask-mode: alpha;
  pointer-events: none;
}

/* 06.4 按钮组与文本输入框 */
#send_form #nonQRFormItems > :is(#leftSendForm, #rightSendForm) {
  grid-row: 1;
  flex-direction: row;
  flex-wrap: wrap;
  align-items: center;
  align-content: center;
  width: auto;
  min-width: 0;
  height: auto;
  gap: 0;
  padding: 0;
}

#send_form #nonQRFormItems > #leftSendForm {
  grid-column: 1;
  justify-content: flex-start;
}

#send_form #nonQRFormItems > #rightSendForm {
  grid-column: 3;
  justify-content: flex-end;
}

#send_form #nonQRFormItems > #send_textarea {
  grid-column: 2;
  grid-row: 1;
  box-sizing: border-box;
  width: 100%;
  min-width: 0;
  min-height: var(--wd-bottom-input-height);
  height: auto;
  max-height: 50dvh;
  margin: 0;
  padding-block: max(8px, calc((var(--wd-bottom-input-height) - 1.5em - 3px) / 2));
  padding-inline: clamp(6px, 1.6cqw, 14px);
  border-radius: 0;
  background: rgba(255, 255, 255, 0.6) !important;
  font-size: var(--mainFontSize);
  line-height: 1.5;
  text-align: left;
  overflow-y: auto;
}

#send_form #nonQRFormItems > #send_textarea:focus-visible {
  outline: 1px solid var(--wd-bottom-hint-color);
  outline-offset: 0;
}

/* --- 通用输入框提示词自定义 by 墨千尾 --- */
/* 06.5 🦋 空输入提示文字 */
/* 提示与输入框共用网格位置，输入后隐藏；不支持 :has 时沿用原生提示。 */
@supports selector(:has(#send_textarea)) {
  #nonQRFormItems > #send_textarea::placeholder {
    color: transparent !important;
    opacity: 0;
  }

  #nonQRFormItems:has(> #send_textarea:placeholder-shown)::before {
    content: "「心跳如蝶翼震颤」";
    grid-column: 2;
    grid-row: 1;
    position: relative;
    z-index: 1;
    min-width: 0;
    padding-inline: 4px;
    color: var(--wd-bottom-hint-color);
    font-family: var(--mainFontFamily);
    font-weight: normal;
    font-size: clamp(12px, 1.896cqw, 17px);
    line-height: 1.5;
    text-align: center;
    white-space: nowrap;
    overflow: hidden;
    pointer-events: none;
    user-select: none;
  }
}

/* --- 手机端输入框换行 by Nakari --- */
/* 06.5a 🦋 手机端输入框聚焦换行修复（适配酒馆 <=1000px 移动布局）。
   不聚焦仍保持原来三列布局；聚焦后按钮位于第一行，真实 textarea 独占第二行。
   注意自定义提示词只是 ::before，不可只修改它而不修改 textarea 本身。 */
@media screen and (max-width: 1000px) {
  /* 聚焦后用有名字的网格区域，避免隐式列及原始 grid-row:1 残留。 */
  #send_form:has(#send_textarea:focus) > #nonQRFormItems {
    display: grid !important;
    grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
    grid-template-rows: auto auto !important;
    grid-template-areas: "wd-left wd-right" "wd-input wd-input" !important;
    align-items: center;
    row-gap: clamp(6px, 1.4cqw, 12px);
    /* 原主题左边距约 4.5cqw，右边距只有 0.3cqw：聚焦时改为左右对称。 */
    box-sizing: border-box !important;
    width: 100% !important;
    max-width: 100% !important;
    min-width: 0 !important;
    padding-inline: clamp(12px, 4.5cqw, 40px) !important;
  }

  #send_form:has(#send_textarea:focus) #nonQRFormItems > #leftSendForm {
    grid-area: wd-left !important;
    grid-column: 1 !important;
    grid-row: 1 !important;
    justify-self: start;
    flex-wrap: nowrap !important;
    min-width: 0;
  }

  #send_form:has(#send_textarea:focus) #nonQRFormItems > #rightSendForm {
    grid-area: wd-right !important;
    grid-column: 2 !important;
    grid-row: 1 !important;
    justify-self: end;
    flex-wrap: nowrap !important;
    min-width: 0;
  }

  /* 直接强制重新定位真正可编辑的 textarea，而不是仅移动伪元素。 */
  #send_form:has(#send_textarea:focus) #nonQRFormItems > #send_textarea {
    grid-area: wd-input !important;
    grid-column: 1 / -1 !important;
    grid-row: 2 !important;
    position: relative !important;
    inset: auto !important;
    justify-self: stretch;
    align-self: stretch;
    display: block !important;
    box-sizing: border-box;
    width: 100% !important;
    min-width: 0 !important;
    max-width: 100% !important;
    margin: 0 !important;
  }

  /* 自定义提示词与第二行的真实输入框重叠，输入内容后按原规则消失。 */
  #send_form:has(#send_textarea:focus) #nonQRFormItems:has(> #send_textarea:placeholder-shown)::before {
    grid-area: wd-input !important;
    grid-column: 1 / -1 !important;
    grid-row: 2 !important;
    align-self: center;
    justify-self: stretch;
    pointer-events: none;
  }
}

/* 06.6 🦋 功能按钮素材、尺寸与系统配色模式图标 */
/* 菜单：图片水平翻转 */
#nonQRFormItems #options_button {
  --wd-bottom-icon: url("https://qianqianqiu.date/file/studio/KNMihboSgOdhwvFO.png");
  --wd-bottom-icon-size: calc(var(--wd-bottom-button) * 0.6336);
  --wd-bottom-icon-flip: -1;
  --wd-bottom-native-icon: "\f0c9";
  order: 0;
}

/* 扩展 */
#nonQRFormItems #extensionsMenuButton {
  --wd-bottom-icon: url("https://qianqianqiu.date/file/studio/qIHdzrMVqBQ7fqXH.png");
  --wd-bottom-icon-size: calc(var(--wd-bottom-button) * 0.5184);
  --wd-bottom-native-icon: "\f0d0";
  order: 1;
}

/* QR 助手 */
#nonQRFormItems #quick-reply-rocket-button {
  --wd-bottom-icon: url("https://qianqianqiu.date/file/studio/IGDumrQsJcfC60YG.png");
  --wd-bottom-icon-size: calc(var(--wd-bottom-button) * 0.6336);
  --wd-bottom-native-icon: "\f135";
  order: 0;
}

/* 发送 */
#nonQRFormItems #send_but {
  --wd-bottom-icon: url("https://qianqianqiu.date/file/studio/Y5u9Z9WEdWNas1Me.png");
  --wd-bottom-icon-size: calc(var(--wd-bottom-button) * 0.648);
  --wd-bottom-native-icon: "\f1d8";
}

/* 停止 */
#nonQRFormItems #mes_stop {
  --wd-bottom-icon: url("https://qianqianqiu.date/file/studio/KNMihboSgOdhwvFO.png");
  --wd-bottom-icon-size: calc(var(--wd-bottom-button) * 0.6336);
  --wd-bottom-native-icon: "\f28d";
}

/* 06.7 按钮绘制、悬停与焦点 */
/* 保留原生显隐与发送按钮的动态宽度；仅替换图标绘制层。 */
#nonQRFormItems :is(#options_button, #extensionsMenuButton, #quick-reply-rocket-button, #send_but, #mes_stop) {
  position: relative;
  flex: 0 0 auto;
  box-sizing: border-box;
  width: var(--wd-bottom-button);
  height: max(40px, calc(var(--wd-bottom-button) * 0.6));
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: 4px;
  background: transparent !important;
  opacity: 1;
  overflow: visible;
}

#nonQRFormItems :is(#options_button, #extensionsMenuButton, #quick-reply-rocket-button, #send_but, #mes_stop)::before {
  content: none !important;
}

#nonQRFormItems :is(#mes_stop, #quick-reply-rocket-button) > :is(i, img, svg) {
  display: none !important;
}

#nonQRFormItems :is(#options_button, #extensionsMenuButton, #quick-reply-rocket-button, #send_but, #mes_stop)::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  width: var(--wd-bottom-icon-size);
  height: var(--wd-bottom-icon-size);
  background: var(--wd-bottom-icon) center / contain no-repeat;
  transform: translate(-50%, -50%) scaleX(var(--wd-bottom-icon-flip, 1));
  transition: transform 180ms ease;
  pointer-events: none;
}

#nonQRFormItems :is(#options_button, #extensionsMenuButton, #quick-reply-rocket-button, #send_but, #mes_stop):hover::after {
  transform: translate(-50%, -50%) scaleX(var(--wd-bottom-icon-flip, 1)) scale(1.2);
}

#nonQRFormItems :is(#options_button, #extensionsMenuButton, #quick-reply-rocket-button, #send_but, #mes_stop):focus-visible {
  outline: 2px solid var(--wd-bottom-hint-color);
  outline-offset: -2px;
}

/* ===== 07 | 抽屉菜单与表单控件 ===== */

/* --- 菜单栏全屏化 by Nakari --- */
/* 07.1 面板高度、背景与标题 */
/* 面板高度扣除顶栏；展开与拖动状态使用相同尺寸，保留原生滚动。 */
.drawer-content,
.drawer-content.openDrawer,
#movingDivs > .drawer-content,
#left-nav-panel,
#right-nav-panel,
#character_popup {
  /* 🦋 表单底色、线条与勾选／折叠图标 */
  --wd-menu-field: rgba(255, 255, 255, 0.4);
  --wd-menu-line: #7B97BA;
  --wd-menu-unchecked: url("https://qianqianqiu.date/file/studio/qIHdzrMVqBQ7fqXH.png");
  --wd-menu-checked: url("https://qianqianqiu.date/file/studio/VbDmaAFTXWg6HaWB.png");
  --wd-menu-arrow: url("https://qianqianqiu.date/file/studio/KNMihboSgOdhwvFO.png");
  top: var(--topBarBlockSize);
  height: calc(100dvh - var(--topBarBlockSize));
  max-height: calc(100dvh - var(--topBarBlockSize));
  min-height: 0 !important;
  box-sizing: border-box;
  border-radius: 0 !important;
}

/* --- 其他页面背景图 by Deleted User --- */
.drawer-content {
  background-image: url("https://qianqianqiu.date/file/studio/pylhXJgtjHge45eK.png");
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
}

/* --- 抽屉菜单标题样式 by Nakari --- */
.drawer-content .inline-drawer-toggle.inline-drawer-header,
.drawer-content .standoutHeader,
.drawer-content h4 {
  background-color: transparent !important;
  background-image: none !important;
  border: 0 !important;
}

/* --- 菜单输入框与选择框样式 by Nakari --- */
/* 07.2 文字、数字输入框与选择框 */
:is(.drawer-content, #left-nav-panel, #right-nav-panel, #character_popup) :is(
  textarea, select, input:not([type]), input[type="text"], input[type="search"],
  input[type="number"], input[type="password"], input[type="email"],
  input[type="url"], input[type="tel"], .select2-selection
) {
  background-color: var(--wd-menu-field) !important;
  border: 1px solid rgba(255, 255, 255, 1) !important;
  border-radius: 0 !important;
  outline: none;
}

/* --- 抽屉下拉箭头自定义图标 by Nakari --- */
/* 普通选择框隐藏装饰箭头；栏目折叠入口显示蝴蝶，并在展开时翻转。 */
@media not (forced-colors: active) {
  :is(.drawer-content, #left-nav-panel, #right-nav-panel, #character_popup)
  :is(select:not([multiple]):not([size]), select:not([multiple])[size="1"], .select2-selection--single) {
    background-image: none !important;
  }

  :is(.drawer-content, #left-nav-panel, #right-nav-panel, #character_popup)
  :is(select:not([multiple]):not([size]), select:not([multiple])[size="1"]) {
    -webkit-appearance: none;
    -moz-appearance: none;
    appearance: none;
    padding-right: 5px;
  }

  :is(.drawer-content, #left-nav-panel, #right-nav-panel, #character_popup)
  .select2-selection--single .select2-selection__arrow {
    visibility: hidden;
  }

  :is(.drawer-content, #left-nav-panel, #right-nav-panel, #character_popup) .inline-drawer-icon::before {
    content: "";
    display: inline-block;
    width: 28px;
    height: 28px;
    background: var(--wd-menu-arrow) center / contain no-repeat;
    vertical-align: middle;
    pointer-events: none;
  }

  :is(.drawer-content, #left-nav-panel, #right-nav-panel, #character_popup) .inline-drawer-icon.up::before {
    transform: scaleX(-1);
  }
}

/* 多选框内的搜索输入保持透明，避免半透明底色重复叠加。 */
:is(.drawer-content, #left-nav-panel, #right-nav-panel, #character_popup)
.select2-selection .select2-search__field {
  background-color: transparent !important;
  border: 0 !important;
}

/* --- 滑动条与自定义滑块按钮 by Nakari --- */
/* 07.3 原生滑块：细线轨道与蝴蝶手柄 */
:is(.drawer-content, #left-nav-panel, #right-nav-panel, #character_popup) input[type="range"] {
  -webkit-appearance: none !important;
  appearance: none !important;
  box-sizing: border-box;
  height: 2px !important;
  min-height: 2px !important;
  max-height: 2px !important;
  padding: 0 !important;
  border: 0 !important;
  border-radius: 1px !important;
  background: var(--wd-menu-line) !important;
  /* 单独覆盖原生滑块的高优先级阴影。 */
  box-shadow: none !important;
  outline: none;
  overflow: visible;
}

/* 成对的滑块与数值框贴合，顶部为手柄预留空间。 */
:is(.drawer-content, #left-nav-panel, #right-nav-panel, #character_popup)
input[type="range"].neo-range-slider:has(+ input.neo-range-input) {
  margin: 12px 0 0 !important;
  border-radius: 1px 1px 0 0 !important;
}

:is(.drawer-content, #left-nav-panel, #right-nav-panel, #character_popup)
input[type="range"].neo-range-slider + input.neo-range-input {
  margin-top: 0 !important;
}

/* WebKit 与 Firefox 的轨道、手柄分别声明。 */
:is(.drawer-content, #left-nav-panel, #right-nav-panel, #character_popup) input[type="range"]::-webkit-slider-runnable-track {
  height: 2px;
  border: 0;
  border-radius: 1px;
  background: var(--wd-menu-line);
}

:is(.drawer-content, #left-nav-panel, #right-nav-panel, #character_popup) input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  box-sizing: border-box;
  width: 24px;
  height: 24px;
  margin-top: -11px;
  border: 0;
  border-radius: 0;
  background: transparent var(--wd-menu-unchecked) center / contain no-repeat;
  box-shadow: none;
}

:is(.drawer-content, #left-nav-panel, #right-nav-panel, #character_popup) input[type="range"]::-moz-range-track {
  height: 2px;
  border: 0;
  border-radius: 1px;
  background: var(--wd-menu-line);
}

:is(.drawer-content, #left-nav-panel, #right-nav-panel, #character_popup) input[type="range"]::-moz-range-progress {
  height: 2px;
  border-radius: 1px;
  background: var(--wd-menu-line);
}

:is(.drawer-content, #left-nav-panel, #right-nav-panel, #character_popup) input[type="range"]::-moz-range-thumb {
  box-sizing: border-box;
  width: 24px;
  height: 24px;
  border: 0;
  border-radius: 0;
  background: transparent var(--wd-menu-unchecked) center / contain no-repeat;
  box-shadow: none;
}

/* 07.4 Zen 滑块：图片位于细线上，真实可编辑数值位于图片下方。 */
/* 保留原生手柄宽度与动态横坐标，支持拖动和键盘编辑。 */
:is(.drawer-content, #left-nav-panel, #right-nav-panel, #character_popup) [id$="_zenslider"].ui-slider {
  height: 2px;
  margin: 16px 0 28px;
  border: 0 !important;
  border-radius: 1px !important;
  outline: none;
  background: var(--wd-menu-line);
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
}

:is(.drawer-content, #left-nav-panel, #right-nav-panel, #character_popup) [id$="_zenslider"] > .ui-slider-handle {
  top: -11px;
  box-sizing: border-box;
  height: auto;
  min-height: 44px;
  padding: 24px 2px 0;
  border: 0 !important;
  border-radius: 0;
  outline: none;
  background: var(--wd-menu-unchecked) center top / 24px 24px no-repeat;
  font-size: 12px;
  line-height: 20px;
  text-align: center;
  white-space: nowrap;
}

/* --- 勾选框图片与选中状态 by Nakari --- */
/* 07.5 蝴蝶勾选框：按原生选中状态切换图片。 */
/* 保留标签关系、原生显隐与禁用行为；混合状态用虚线标识。 */
:is(.drawer-content, #left-nav-panel, #right-nav-panel, #character_popup) input[type="checkbox"] {
  -webkit-appearance: none;
  appearance: none;
  box-sizing: border-box;
  width: 24px;
  height: 24px;
  flex-shrink: 0;
  border: 0;
  border-radius: 0;
  outline: none;
  transform: none;
  background: transparent var(--wd-menu-unchecked) center / contain no-repeat;
}

:is(.drawer-content, #left-nav-panel, #right-nav-panel, #character_popup) input[type="checkbox"]::before {
  content: none;
}

:is(.drawer-content, #left-nav-panel, #right-nav-panel, #character_popup) input[type="checkbox"]:checked {
  background-image: var(--wd-menu-checked);
}

:is(.drawer-content, #left-nav-panel, #right-nav-panel, #character_popup) input[type="checkbox"]:indeterminate {
  outline: 1px dashed var(--wd-menu-line);
  outline-offset: 2px;
}

/* 07.6 禁用状态与键盘焦点 */
:is(.drawer-content, #left-nav-panel, #right-nav-panel, #character_popup)
:is(input, textarea, select):disabled:not([type="range"]):not(.neo-range-input) {
  opacity: 0.55;
}

:is(.drawer-content, #left-nav-panel, #right-nav-panel, #character_popup)
:is(input[type="range"], input.neo-range-input, [id$="_zenslider"].ui-slider) {
  opacity: 1;
}

/* 模糊与阴影设置的外层保持清晰，覆盖脚本写入的半透明状态。 */
:is(.drawer-content, #left-nav-panel, #right-nav-panel, #character_popup)
:is(#blur-strength-block, #shadow-width-block) {
  opacity: 1 !important;
}

:is(.drawer-content, #left-nav-panel, #right-nav-panel, #character_popup)
:is(input[type="checkbox"], input[type="radio"], input[type="range"], .ui-slider-handle):focus-visible {
  outline: 2px solid var(--wd-menu-line);
  outline-offset: 2px;
}

/* ===== 08 | 预设与角色管理 ===== */

/* 08.1 预设列表：透明背景与启停文字颜色。 */
#completion_prompt_manager #completion_prompt_manager_list,
#completion_prompt_manager #completion_prompt_manager_list > .completion_prompt_manager_prompt {
  background-color: transparent !important;
  background-image: none !important;
}

#completion_prompt_manager .completion_prompt_manager_header {
  color: var(--SmartThemeBodyColor) !important;
}

#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_name .fa-solid {
  color: inherit !important;
}

#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name,
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name .prompt-manager-inspect-action {
  color: #576C85 !important;
}

/* 08.2 角色详情：纵向排布头像框与操作控件。 */
#form_create[actiontype="editcharacter"] #avatar_div {
  flex-direction: column;
  align-items: stretch;
  gap: 8px;
  min-width: 0;
}

/* --- 贴图在容器上溢出显示 by 蝶 --- */
/* 🦋 相框按 2084∶2740 等比缩放，最大宽度为 480px。 */
#form_create[actiontype="editcharacter"] #avatar_div_div {
  position: relative;
  isolation: isolate;
  display: block;
  flex: 0 0 auto;
  width: min(100%, 480px);
  max-width: 100%;
  min-width: 0;
  height: auto;
  aspect-ratio: 2084 / 2740;
  box-sizing: border-box;
  margin: 0 auto;
  padding: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  overflow: visible;
}

/* 真实头像填满透明开口；装饰层不拦截上传头像的点击。 */
#form_create[actiontype="editcharacter"] #avatar_div_div > #avatar_load_preview {
  position: absolute;
  top: 31.204380%;
  left: 32.341651%;
  width: 50.335893%;
  height: 33.138686%;
  max-width: none;
  max-height: none;
  min-width: 0;
  min-height: 0;
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: 0;
  object-fit: cover;
  object-position: center;
  z-index: 0;
}

#form_create[actiontype="editcharacter"] #avatar_div_div::after {
  content: "";
  position: absolute;
  inset: 0;
  background: url("https://qianqianqiu.date/file/studio/4pDCPqHSfS2qhkLc.png") center / contain no-repeat;
  z-index: 1;
  pointer-events: none;
}

#form_create[actiontype="editcharacter"] #avatar_controls {
  flex: 0 0 auto;
  width: 100%;
  min-width: 0;
  height: auto;
  padding: 0;
}

/* ===== 09 | 通知提示 ===== */

/* --- Toast 提示框美化 by hy --- */
/* 09.1 半透明白底、蓝色细边与蝴蝶图标 */
/* 保留通知位置、关闭按钮、点击行为与淡入淡出。 */
#toast-container > .toast {
  box-sizing: border-box;
  max-width: min(250px, calc(100vw - 24px));
  min-height: 46px;
  padding: 10px 15px 10px 50px;
  border: 1px solid #7B97BA;
  border-radius: 0;
  background-color: rgba(255, 255, 255, 0.3) !important;
  background-size: 23px auto;
  background-repeat: no-repeat;
  background-position: 12px center;
  color: #334E69;
  line-height: 1.5;
  overflow-wrap: anywhere;
}

/* 09.2 🦋 成功、错误、信息与警告图标 */
#toast-container > .toast-success {
  background-image: url("https://qianqianqiu.date/file/studio/qIHdzrMVqBQ7fqXH.png") !important;
}

#toast-container > .toast-error {
  background-image: url("https://qianqianqiu.date/file/studio/VbDmaAFTXWg6HaWB.png") !important;
}

#toast-container > .toast-info {
  background-image: url("https://qianqianqiu.date/file/studio/KNMihboSgOdhwvFO.png") !important;
}

#toast-container > .toast-warning {
  background-image: url("https://qianqianqiu.date/file/studio/Y5u9Z9WEdWNas1Me.png") !important;
}

/* 09.3 标题、正文、链接与关闭按钮 */
#toast-container > .toast > .toast-title {
  color: inherit;
  font-size: 13px;
}

#toast-container > .toast > .toast-message {
  color: inherit;
  font-size: 12px;
}

#toast-container > .toast .toast-message a {
  color: #3E5F84;
  text-decoration: underline;
}

#toast-container > .toast > .toast-close-button {
  color: inherit;
}

/* ===== 10 | 启动加载页 ===== */

/* --- 加载页面美化 by Deleted User --- */
/* 10.1 全屏背景与加载弹窗 */
/* 同时覆盖独立预加载层与弹窗背景；保留原生显隐和退场。 */
#preloader {
  position: fixed;
  margin: 0;
  padding: 0;
  top: 0;
  left: 0;
  z-index: 999999;
  width: 100vw;
  height: 100vh;
  width: 100dvw;
  height: 100dvh;
  border: 0 !important;
  border-radius: 0 !important;
}

#preloader,
.popup:has(#loader)::backdrop {
  background: transparent url("https://qianqianqiu.date/file/studio/pylhXJgtjHge45eK.png") center / cover no-repeat !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}

.popup:has(#loader) {
  background: transparent !important;
  border: 0 !important;
  border-radius: 0 !important;
}

/* 10.2 浮动动画与加载图标 */
@keyframes wd-loader-float {
  0%, 100% {
    transform: translateY(0);
  }

  50% {
    transform: translateY(-12px);
  }
}

#load-spinner {
  /* 🦋 图标最大 180px，不超过视口短边的 40%。 */
  --spinner-size: min(180px, 40vmin);
  position: absolute;
  top: calc(50% - var(--spinner-size) / 2);
  left: calc(50% - var(--spinner-size) / 2);
  width: var(--spinner-size);
  height: var(--spinner-size);
  background: transparent url("https://qianqianqiu.date/file/studio/LMYyam475CgeoWKa.png") center / contain no-repeat !important;
  border: 0 !important;
  display: flex;
  align-items: center;
  justify-content: center;
  animation: wd-loader-float 1.5s ease-in-out infinite !important;
  transition: opacity var(--animation-duration-2x, 400ms) ease-out;
}

/* 10.3 清除原生齿轮、启动标志与提示文字 */
#load-spinner::before,
#load-spinner::after {
  content: none !important;
  display: none !important;
}

#loader.splash-screen > .splash-logo,
#loader.splash-screen > .splash-message {
  display: none !important;
}

/* ===== 11 | 屏幕适配与辅助模式 ===== */

/* 11.1 窄屏：聊天区与顶栏全宽，导航按钮按视口分配空间。 */
@media screen and (max-width: 1000px) {
  #sheld,
  #top-bar,
  #top-settings-holder {
    width: 100% !important;
    max-width: 100%;
  }

  #top-bar,
  body.no-blur #top-bar {
    --wd-top-fade-reach: clamp(60px, 10vw, 100px);
  }

  #top-settings-holder {
    --wd-top-icon-box-size: min(var(--topBarBlockSize), 10vw);
  }
}

/* --- PC 端菜单栏全屏化 by Nakari --- */
/* 11.2 桌面侧栏：左右面板使用完整视口高度。 */
@media (min-width: 768px) {
  #left-nav-panel,
  #right-nav-panel {
    top: 0 !important;
    height: 100dvh !important;
    max-height: 100dvh !important;
  }
}

/* 11.3 极窄聊天容器：微调名字、统计信息与时间字号。 */
@container (max-width: 360px) {
  #chat > .mes:is([is_system="false"], [is_system="true"]:not(.smallSysMes, .toolCall, [ch_name="SillyTavern System"])) {
    --wd-name-size: 8px;
    --wd-stats-size: 6px;
    --wd-time-size: 5.5px;
  }
}

/* 11.4 减少动态效果：关闭加载浮动与图标缩放过渡。 */
@media (prefers-reduced-motion: reduce) {
  #load-spinner {
    animation: none !important;
  }

  #top-settings-holder > .drawer:nth-of-type(-n+10) > .drawer-toggle > .drawer-icon::after {
    transition: none;
  }

  #nonQRFormItems :is(#options_button, #extensionsMenuButton, #quick-reply-rocket-button, #send_but, #mes_stop)::after {
    transition: none;
  }
}

/* 11.5 系统强制配色：恢复原生勾选、滑块、功能图标与输入提示。 */
@media (forced-colors: active) {
  body input[type="checkbox"],
  body input[type="checkbox"]:checked {
    -webkit-appearance: auto;
    appearance: auto;
    background: none;
    border: initial;
  }

  .select2-container .select2-results__option::before {
    forced-color-adjust: none;
    border-color: CanvasText;
    background: Canvas;
  }

  .select2-container .select2-results__option.select2-results__option--selected::before {
    background-color: CanvasText;
  }

  :is(.drawer-content, #left-nav-panel, #right-nav-panel, #character_popup) input[type="checkbox"],
  :is(.drawer-content, #left-nav-panel, #right-nav-panel, #character_popup) input[type="checkbox"]:checked {
    -webkit-appearance: auto;
    appearance: auto;
    background: none;
  }

  :is(.drawer-content, #left-nav-panel, #right-nav-panel, #character_popup) input[type="range"]::-webkit-slider-thumb {
    background: ButtonText;
    border: 1px solid Canvas;
    border-radius: 50%;
  }

  :is(.drawer-content, #left-nav-panel, #right-nav-panel, #character_popup) input[type="range"]::-moz-range-thumb {
    background: ButtonText;
    border: 1px solid Canvas;
    border-radius: 50%;
  }

  :is(.drawer-content, #left-nav-panel, #right-nav-panel, #character_popup) [id$="_zenslider"] > .ui-slider-handle {
    padding-top: 0;
    min-height: 24px;
    border: 1px solid ButtonText !important;
    background: Canvas;
    color: CanvasText !important;
  }

  #nonQRFormItems :is(#options_button, #extensionsMenuButton, #quick-reply-rocket-button, #send_but, #mes_stop)::after,
  #nonQRFormItems:has(> #send_textarea:placeholder-shown)::before {
    content: none;
  }

  #nonQRFormItems :is(#options_button, #extensionsMenuButton, #quick-reply-rocket-button, #send_but, #mes_stop)::before {
    content: var(--wd-bottom-native-icon) !important;
    display: block;
    color: ButtonText;
    font-family: "Font Awesome 6 Free";
    font-weight: 900;
    font-size: var(--bottomFormIconSize);
    line-height: max(40px, calc(var(--wd-bottom-button) * 0.6));
    text-align: center;
  }

  #nonQRFormItems > #send_textarea::placeholder {
    color: GrayText !important;
    opacity: 1;
  }
}
